Lemma sc_call_pev : apev_ctor_stmt H ->
  forall (s : as_St H) (LB : list block) (LF : list fframe) (S ioc regb cfgb lo shi spa ff fp : Z) (sp tp : word)
         (saved gap : list cell) (h32 j472 shb : list byte) (errv : word) (cs1 cs2 lc : list cell) (jm : list byte) (m : mem)
         (rax gp t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 xs2 xs3 xs5 xs6 xs7 xs9 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32) (Q : machine_state -> Prop),
  sc_invt H s LB LF S ioc regb cfgb lo shi spa ff fp sp saved gap h32 j472 shb errv (cs1 ++ [CB 56 jm] ++ cs2) lc m ->
  Z.of_nat (cells_size cs1) = 120 ->
  sc_side H LB LF S ioc regb cfgb lo shi spa ff fp sp tp ->
  bv_unsigned rax mod 2 = 0 ->
